int cypress_open(struct tty_struct *tty, struct usb_serial_port *port)
{
    int result;

    if (!port)
        return -ENODEV;

    usb_serial_debug_func(debug, "cypress_open");
    result = usb_serial_generic_open(tty, port);
    if (result)
        return result;

    usb_clear_halt(port->serial->dev, port->read_urb->pipe);
    usb_clear_halt(port->serial->dev, port->write_urb->pipe);

    tty->low_latency = 1;
    tty->no_flow_ctrl = 1;

    result = usb_submit_urb(port->read_urb, GFP_KERNEL);
    if (result) {
        dev_err(&port->dev, "failed to submit read urb: %d\n", result);
        port->port.flags &= ~ASYNCB_INITIALIZED;
        usb_serial_generic_close(tty, port);
        return result;
    }

    return 0;
}

int open_cypress_usb_serial_port(struct tty_struct *tty, struct usb_serial_port *port)
{
    int ret;

    if (!port || !tty)
        return -EINVAL;

    if (!usb_serial_port_available(port))
        return -EBUSY;

    usb_serial_unblock_traffic(port);
    usb_serial_clear_halt(port->dev);

    tty->low_latency = 1;
    tty->no_job_control = 1;
    tty->termios = *tty->driver->termios;

    ret = usb_submit_urb(port->interrupt_urb, GFP_KERNEL);
    if (ret) {
        dev_err(&port->dev->dev, "Failed to submit interrupt URB: %d\n", ret);
        usb_serial_mark_port_dead(port);
        return ret;
    }

    return 0;
}

int cypress_open(struct tty_struct *tty, struct usb_serial_port *port)
{
    int result;

    /* Check if the communication is operational */
    if (!port->serial->num_ports)
        return -ENODEV;

    /* Clear any halted states on the USB device */
    usb_clear_halt(port->serial->dev, port->read_urb->pipe);
    usb_clear_halt(port->serial->dev, port->write_urb->pipe);

    /* Reset read/write statistics */
    port->read_urb->actual_length = 0;
    port->write_urb->actual_length = 0;

    /* Set the terminal I/O settings */
    if (tty)
        tty->low_latency = 1;

    /* Prepare USB interrupt transfer for reading data */
    result = submit_urbs(port);
    if (result) {
        dev_err(&port->dev, "Failed to submit read request\n");
        port->serial->port[0].port_state = PORT_DEAD;
        return result;
    }

    return 0;
}

int cypress_open(struct tty_struct *tty, struct usb_serial_port *port)
{
    int result;

    /* Check if communication is operational */
    if (!port->port.count) {
        /* Clear halted states and reset read/write statistics */
        usb_serial_generic_open(tty, port);
        usb_clear_halt(port->serial->dev, port->read_urb->pipe);
        usb_clear_halt(port->serial->dev, port->write_urb->pipe);

        /* Set terminal I/O settings */
        result = tty_set_termios(tty);
        if (result)
            return result;

        /* Prepare the USB interrupt transfer for reading data */
        result = usb_submit_urb(port->read_urb, GFP_KERNEL);
        if (result) {
            dev_err(&port->dev, "Failed to submit read urb: %d\n", result);
            port->port.flags |= ASYNC_PORT_DEAD;
            return result;
        }
    }

    return 0;
}

int cypress_open(struct tty_struct *tty, struct usb_serial_port *port)
{
    int result;

    if (!tty) {
        dev_dbg(&port->dev, "no tty for open\n");
        return -ENODEV;
    }

    usb_serial_debug_function(__func__, port->number);

    if (!port->open_count) {
        result = usb_clear_halt(port->serial->dev, port->read_urb->pipe);
        if (result)
            dev_dbg(&port->dev, "usb_clear_halt read failed with %d\n", result);

        result = usb_clear_halt(port->serial->dev, port->write_urb->pipe);
        if (result)
            dev_dbg(&port->dev, "usb_clear_halt write failed with %d\n", result);

        tty->low_latency = 1;
        tty->no_flip = 1;

        result = usb_submit_urb(port->read_urb, GFP_KERNEL);
        if (result) {
            dev_err(&port->dev, "failed to submit urb: %d\n", result);
            port->port.dead = 1;
            return result;
        }
    }

    port->port.flags |= ASYNCB_INITIALIZED;
    port->open_count++;

    return 0;
}
